function collectNoises() {
  return [...$("noise-list").querySelectorAll(".noise-source-card")].map((card) => {
    const field = (name) => card.querySelector(`[data-field="${name}"]`);
    return {
      label: field("label").value.trim() || "Noise",
      noise_type: field("noise_type").value,
      azimuth_deg: Number(field("azimuth_deg").value || 0),
      elevation_deg: Number(field("elevation_deg").value || 0),
      gain: Number(field("gain").value || 1),
      prebaked_path: field("prebaked_path")?.value.trim() || "",
      source_profile: field("source_profile")?.value.trim() || GOLD_STANDARD_SOURCE_PROFILE,
      source_profile_parameters: readJsonField(field("source_profile_parameters")) || {},
      motion_mode: field("motion_mode")?.value.trim() || "looming",
      trajectory_snapshot: readJsonField(field("trajectory_snapshot"))
    };
  });
}

function collectAudioFiles() {
  const result = { looming: [], prestimulus: [] };
  const cards = [
    ...$("audio-list").querySelectorAll(".audio-source-card"),
    ...$("snippet-list").querySelectorAll(".audio-source-card"),
  ];
  for (const card of cards) {
    const field = (name) => card.querySelector(`[data-field="${name}"]`);
    const role = field("audio_role").value;
    const item = {
      label: field("label").value.trim() || "Audio file",
      path: field("path").value.trim(),
      target_duration_s: Number(field("target_duration_s").value || 4),
      render_mode: role === "spatialize" ? "spatialize" : "preserve",
      tone_type: field("tone_type")?.value.trim() || "",
      gain: Number(field("gain").value || 1),
      placement: normalizeSnippetPlacement(field("placement")?.value),
      target_source_label: field("target_source_label")?.value.trim() || "",
      phase: field("phase")?.value.trim() || "",
      gap_s: Math.max(0, Number(field("gap_s")?.value || 0)),
      motion_mode: field("motion_mode")?.value || (role === "prestimulus" ? "stationary" : "looming"),
      trajectory_snapshot: readJsonField(field("trajectory_snapshot"))
    };
    if (role === "prestimulus") {
      result.prestimulus.push(item);
    } else {
      result.looming.push(item);
    }
  }
  return result;
}

async function applyDesign() {
  if (!ensureEditableProject()) return;
  if (staticModeActive) {
    state.design = collectPayload().design;
    await window.PPSDesigner?.drafts?.save(state);
  } else {
    state = await api("/api/design", {
      method: "POST",
      body: JSON.stringify(collectPayload())
    });
  }
  renderAll();
  updateViewer();
  const staleSegments = Object.values(state.project_segments || {}).filter((segment) => segment.status === "stale");
  showToast(staticModeActive ? "Browser draft saved locally" : staleSegments.length ? "Design saved; downstream segments need rebake" : "Design saved");
}

function scheduleCustomAutosave() {
  if (!state || !isCustomMode() || isProfileReadonlyMode() || !editModeActive) return;
  window.clearTimeout(autosaveTimer);
  const revision = ++autosaveRevision;
  autosaveTimer = window.setTimeout(() => autosaveCustomDraft(revision).catch(reportError), 700);
}

async function autosaveCustomDraft(revision) {
  if (revision !== autosaveRevision || !state || !isCustomMode() || isProfileReadonlyMode() || !editModeActive) return;
  const payload = collectPayload();
  if (staticModeActive) {
    state.design = payload.design;
    await window.PPSDesigner?.drafts?.save(state);
  } else {
    const updated = await api("/api/design", { method: "POST", body: JSON.stringify(payload) });
    if (revision !== autosaveRevision) return;
    state = updated;
    renderWorkflow();
    document.dispatchEvent(new CustomEvent("pps-designer-saved"));
  }
}

async function continueWorkflowStep(stepId) {
  if (!ensureEditableProject()) return;
  if (staticModeActive) {
    state.design = collectPayload().design;
    await window.PPSDesigner?.drafts?.save(state);
  } else {
    state = await api("/api/design", {
      method: "POST",
      body: JSON.stringify(collectPayload())
    });
  }
  renderAll();
  updateViewer();
  const step = getWorkflowStep(stepId);
  if (!step || step.complete) {
    const next = NEXT_STEP[stepId];
    if (next) {
      scrollToStep(next);
    }
    showToast("Step saved");
    return;
  }
  showToast(step.missing.join(" "));
  scrollToStep(stepId);
}

async function loadTemplate() {
  if (templateLoadInFlight) return;
  const select = $("template-select");
  const choice = selectedProfileChoice(select.value);
  const id = choice.id;
  if (!id) return;
  if (choice.kind === "custom") {
    await loadCustomProject(id);
    return;
  }
  if (staticModeActive) {
    if (choice.kind === "manual") {
      renderStudy();
      showToast("Start the local companion backend before creating custom studies.");
      return;
    }
    state = await staticStateForTemplate(id);
    staticModeActive = true;
    resetEditMode();
    setConnectionStatus(false, "static profile");
    renderAll();
    updateViewer();
    showToast("Static profile loaded from committed GitHub assets");
    return;
  }
  templateLoadInFlight = true;
  select.disabled = true;
  try {
    state = await api(`/api/templates/${encodeURIComponent(id)}/load`, { method: "POST" });
    await applyStaticProfileInspectionPreview();
    resetEditMode();
    renderAll();
    updateViewer();
    showToast(choice.kind === "manual" ? "Custom design started" : "Profile loaded");
  } finally {
    templateLoadInFlight = false;
    $("template-select").disabled = false;
  }
}

async function loadCustomProject(projectIdOverride = "") {
  const select = $("existing-custom-project");
  const projectId = projectIdOverride || select?.value || "";
  if (!projectId) {
    showToast("Choose a custom study to open");
    return;
  }
  state = await api(`/api/projects/${encodeURIComponent(projectId)}/load`, { method: "POST" });
  resetEditMode();
  renderAll();
  updateViewer();
  showToast("Custom study opened");
  scrollToStep(state.custom_workflow?.current_step || "study");
}

